import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import humanTime from 'flarum/common/helpers/humanTime';
import extractText from 'flarum/common/utils/extractText';
import ItemList from 'flarum/common/utils/ItemList';
import { TABS, tabRoute, trans } from '../../config';
import AdvertiserModal from '../AdvertiserModal';
import ListToolbar from '../ListToolbar';
import RecordsTable from '../RecordsTable';
import StatusPill from '../StatusPill';

/**
 * Who campaigns are reported to.
 *
 * Optional throughout: a forum running only its own house adverts never opens
 * this tab. It exists mainly to own the report link, which is what lets an
 * advertiser check their delivery without an account on the forum.
 */
export default class AdvertisersTab extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    app.placements.advertisers.ensureLoaded();
  }
  view() {
    return m("div", {
      className: "PlacementsTab"
    }, m("p", {
      className: "helpText"
    }, trans('advertisers.help')), m(ListToolbar, {
      state: app.placements.advertisers,
      searchLabel: trans('advertisers.search'),
      actions: m(Button, {
        className: "Button Button--primary",
        icon: "fas fa-plus",
        onclick: () => app.modal.show(AdvertiserModal, {
          onsaved: () => app.placements.advertisers.reload()
        })
      }, trans('advertisers.create'))
    }), m(RecordsTable, {
      state: app.placements.advertisers,
      columns: this.columns(),
      empty: trans('advertisers.none')
    }));
  }
  columns() {
    const items = new ItemList();
    items.add('name', {
      label: trans('advertisers.name_label'),
      sort: 'name',
      content: advertiser => {
        // `hasOne` answers `false`, not undefined, when the relationship was
        // not loaded, so this is bound rather than optionally chained.
        const user = advertiser.user();
        return m("div", {
          className: "PlacementTable-primary"
        }, m("span", {
          className: "PlacementTable-strong"
        }, advertiser.name()), user && m(StatusPill, {
          tone: "neutral",
          icon: "fas fa-user"
        }, user.username()));
      }
    }, 100);
    items.add('contact', {
      label: trans('advertisers.contact_label'),
      content: advertiser => advertiser.contactEmail() ?? m("span", {
        className: "PlacementTable-muted"
      }, trans('advertisers.no_contact'))
    }, 90);
    items.add('link', {
      label: trans('advertisers.link_label'),
      content: advertiser => this.reportLink(advertiser)
    }, 80);
    items.add('campaigns', {
      label: m("span", {
        className: "visually-hidden"
      }, trans('advertisers.campaigns_label')),
      content: advertiser =>
      // The cross-link the page never had. Answering "what is this
      // advertiser running" used to mean reading the whole campaign list
      // and checking each row's advertiser by eye.
      m(Link, {
        href: tabRoute(TABS.campaigns, {
          advertiser: String(advertiser.id())
        }),
        className: "Button Button--text"
      }, trans('advertisers.view_campaigns'))
    }, 70);
    items.add('controls', {
      label: m("span", {
        className: "visually-hidden"
      }, trans('lists.actions')),
      className: 'Table-controls',
      content: advertiser => [m(Button, {
        className: "Button Button--icon Table-controls-item",
        icon: "fas fa-pencil-alt",
        "aria-label": extractText(trans('advertisers.edit')),
        onclick: () => app.modal.show(AdvertiserModal, {
          advertiser,
          onsaved: () => app.placements.advertisers.reload()
        })
      }), m(Button, {
        className: "Button Button--icon Table-controls-item",
        icon: "fas fa-trash-alt",
        "aria-label": extractText(trans('advertisers.delete')),
        onclick: () => this.remove(advertiser)
      })]
    }, -10);
    return items;
  }
  reportLink(advertiser) {
    if (!advertiser.hasReportToken()) {
      return m("span", {
        className: "PlacementTable-muted"
      }, trans('advertisers.no_link'));
    }
    const expires = advertiser.reportTokenExpiresAt();
    return m("div", {
      className: "PlacementTable-primary"
    }, m(StatusPill, {
      tone: "success",
      icon: "fas fa-link"
    }, trans('advertisers.has_link')), expires && m("span", {
      className: "PlacementTable-muted"
    }, humanTime(expires)));
  }

  /**
   * The API has always supported deleting an advertiser and the model has
   * always had the cleanup for it -- campaigns are detached rather than
   * removed -- but there was no way to ask for it from the interface.
   *
   * The confirmation says what happens to the campaigns, because "delete this
   * advertiser?" does not tell somebody whether they are about to lose a year
   * of campaigns with it.
   */
  remove(advertiser) {
    if (!confirm(extractText(trans('advertisers.delete_confirm', {
      name: advertiser.name()
    })))) return;
    advertiser.delete().then(() => {
      app.placements.advertisers.reload();
      // The campaign rows carry the advertiser's name, and they no longer do.
      app.placements.campaigns.reload();
    });
  }
}
flarum.reg.add('datlechin-placements', 'admin/components/tabs/AdvertisersTab', AdvertisersTab);