import Component from 'flarum/common/Component';
import Input from 'flarum/common/components/Input';
import Select from 'flarum/common/components/Select';
import extractText from 'flarum/common/utils/extractText';
import { trans } from '../config';
/**
 * The row above a table: search, the filters that list offers, and its primary
 * action.
 *
 * Searching goes through the state, which waits for a pause in typing before it
 * asks the server -- so the box responds to every keystroke and the network
 * does not.
 */
export default class ListToolbar extends Component {
  view() {
    const {
      state,
      searchLabel,
      choices = [],
      actions
    } = this.attrs;
    return m("div", {
      className: "PlacementToolbar"
    }, m("div", {
      className: "PlacementToolbar-filters"
    }, m(Input, {
      className: "PlacementToolbar-search",
      type: "search",
      prefixIcon: "fas fa-search",
      clearable: true,
      placeholder: extractText(searchLabel),
      ariaLabel: extractText(searchLabel),
      value: state.query,
      onchange: value => state.search(value)
    }), choices.map(choice => this.choice(choice))), actions && m("div", {
      className: "PlacementToolbar-actions"
    }, actions));
  }
  choice(choice) {
    const {
      state
    } = this.attrs;
    return m("label", {
      className: "PlacementToolbar-choice"
    }, m("span", {
      className: "PlacementToolbar-choiceLabel"
    }, choice.label), m(Select, {
      value: state.currentFilter(choice.key),
      options: {
        '': extractText(trans('lists.any')),
        ...choice.options
      },
      onchange: value => state.filterBy(choice.key, value)
    }));
  }
}
flarum.reg.add('datlechin-placements', 'admin/components/ListToolbar', ListToolbar);